"use client";

import "./number-field.css";

import type React from "react";

import { NumberField as BaseNumberField } from "@base-ui/react/number-field";
import { cn } from "tailwind-variants";

import { NumberFieldContext, useNumberFieldContext } from "./number-field.context";
import { numberFieldVariants, type NumberFieldVariants } from "./number-field.variants";

export type NumberFieldProps = NumberFieldVariants &
  React.ComponentProps<typeof BaseNumberField.Root>;

export const NumberFieldRoot = ({ children, className, size, ...props }: NumberFieldProps) => {
  const slots = numberFieldVariants({ size });

  return (
    <NumberFieldContext.Provider value={{ slots }}>
      <BaseNumberField.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseNumberField.Root>
    </NumberFieldContext.Provider>
  );
};

export type NumberFieldGroupProps = React.ComponentProps<typeof BaseNumberField.Group>;

export const NumberFieldGroup = ({ className, ...props }: NumberFieldGroupProps) => {
  const { slots } = useNumberFieldContext();
  return <BaseNumberField.Group className={cn(slots.group(), className)} {...props} />;
};

export type NumberFieldInputProps = React.ComponentProps<typeof BaseNumberField.Input>;

export const NumberFieldInput = ({
  className,
  children: _children,
  dangerouslySetInnerHTML: _dangerouslySetInnerHTML,
  ...props
}: NumberFieldInputProps & { children?: React.ReactNode; dangerouslySetInnerHTML?: any }) => {
  const { slots } = useNumberFieldContext();
  return <BaseNumberField.Input className={cn(slots.input(), className)} {...props} />;
};

export type NumberFieldDecrementProps = React.ComponentProps<typeof BaseNumberField.Decrement>;

export const NumberFieldDecrement = ({
  children,
  className,
  ...props
}: NumberFieldDecrementProps) => {
  const { slots } = useNumberFieldContext();
  return (
    <BaseNumberField.Decrement className={cn(slots.decrement(), className)} {...props}>
      {children ?? (
        <svg className="h-3.5 w-3.5 stroke-current" fill="none" strokeWidth="2" viewBox="0 0 24 24">
          <path d="M5 12h14" />
        </svg>
      )}
    </BaseNumberField.Decrement>
  );
};

export type NumberFieldIncrementProps = React.ComponentProps<typeof BaseNumberField.Increment>;

export const NumberFieldIncrement = ({
  children,
  className,
  ...props
}: NumberFieldIncrementProps) => {
  const { slots } = useNumberFieldContext();
  return (
    <BaseNumberField.Increment className={cn(slots.increment(), className)} {...props}>
      {children ?? (
        <svg className="h-3.5 w-3.5 stroke-current" fill="none" strokeWidth="2" viewBox="0 0 24 24">
          <path d="M12 5v14M5 12h14" />
        </svg>
      )}
    </BaseNumberField.Increment>
  );
};

export type NumberFieldScrubAreaProps = React.ComponentProps<typeof BaseNumberField.ScrubArea>;

export const NumberFieldScrubArea = ({ className, ...props }: NumberFieldScrubAreaProps) => {
  const { slots } = useNumberFieldContext();
  return <BaseNumberField.ScrubArea className={cn(slots.scrubArea(), className)} {...props} />;
};

export type NumberFieldScrubAreaCursorProps = React.ComponentProps<
  typeof BaseNumberField.ScrubAreaCursor
>;

export const NumberFieldScrubAreaCursor = ({
  className,
  ...props
}: NumberFieldScrubAreaCursorProps) => {
  const { slots } = useNumberFieldContext();
  return (
    <BaseNumberField.ScrubAreaCursor
      className={cn(slots.scrubAreaCursor(), className)}
      {...props}
    />
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const numberFieldVariants = tv({
  slots: {
    root: "number-field",
    group: "number-field__group",
    input: "number-field__input",
    decrement: "number-field__decrement",
    increment: "number-field__increment",
    scrubArea: "number-field__scrub-area",
    scrubAreaCursor: "number-field__scrub-area-cursor",
  },
  variants: {
    size: {
      sm: {
        group: "number-field__group--sm",
        input: "number-field__input--sm",
        decrement: "number-field__decrement--sm",
        increment: "number-field__increment--sm",
      },
      md: {
        group: "number-field__group--md",
        input: "number-field__input--md",
        decrement: "number-field__decrement--md",
        increment: "number-field__increment--md",
      },
      lg: {
        group: "number-field__group--lg",
        input: "number-field__input--lg",
        decrement: "number-field__decrement--lg",
        increment: "number-field__increment--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type NumberFieldVariants = VariantProps<typeof numberFieldVariants>;

"use client";

import { createContext, useContext } from "react";

import { numberFieldVariants } from "./number-field.variants";

export type NumberFieldContext = {
  slots: ReturnType<typeof numberFieldVariants>;
};

export const NumberFieldContext = createContext<NumberFieldContext | null>(null);

export const useNumberFieldContext = () => {
  const context = useContext(NumberFieldContext);
  return context ?? { slots: numberFieldVariants() };
};

.number-field {
  @apply flex flex-col items-start gap-1 text-foreground;
}

.number-field__group {
  @apply inline-flex h-9 items-center rounded-md border border-input bg-background shadow-xs transition-colors focus-within:outline-2 focus-within:outline-ring;
}

.number-field__input {
  @apply h-full w-20 border-0 bg-transparent px-2 text-center text-sm font-normal text-foreground tabular-nums outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50;
}

.number-field__decrement,
.number-field__increment {
  @apply flex h-full w-8 items-center justify-center border-0 bg-transparent p-0 text-muted-foreground transition-colors hover:text-foreground hover:bg-accent active:bg-muted disabled:cursor-not-allowed disabled:opacity-50 select-none;
}

.number-field__decrement {
  @apply border-r border-input rounded-l-md;
}

.number-field__increment {
  @apply border-l border-input rounded-r-md;
}

.number-field__scrub-area {
  @apply cursor-ew-resize font-medium select-none text-sm text-foreground;
}

.number-field__scrub-area-cursor {
  @apply drop-shadow-sm;
}

import {
  NumberFieldDecrement,
  NumberFieldGroup,
  NumberFieldIncrement,
  NumberFieldInput,
  NumberFieldRoot,
  NumberFieldScrubArea,
  NumberFieldScrubAreaCursor,
} from "./number-field";

export const NumberField = {
  Decrement: NumberFieldDecrement,
  Group: NumberFieldGroup,
  Increment: NumberFieldIncrement,
  Input: NumberFieldInput,
  Root: NumberFieldRoot,
  ScrubArea: NumberFieldScrubArea,
  ScrubAreaCursor: NumberFieldScrubAreaCursor,
};

export {
  NumberFieldDecrement,
  NumberFieldGroup,
  NumberFieldIncrement,
  NumberFieldInput,
  NumberFieldRoot,
  NumberFieldScrubArea,
  NumberFieldScrubAreaCursor,
};

export type {
  NumberFieldDecrementProps,
  NumberFieldGroupProps,
  NumberFieldIncrementProps,
  NumberFieldInputProps,
  NumberFieldProps,
  NumberFieldScrubAreaCursorProps,
  NumberFieldScrubAreaProps,
} from "./number-field";
export { NumberFieldContext, useNumberFieldContext } from "./number-field.context";
export { type NumberFieldVariants, numberFieldVariants } from "./number-field.variants";
